entries[16110] = { ["name"] = "Rezept: Monsteromelett", ["text"] = "Benötigt Kochkunst (225)\nBenutzen: Lehrt Euch, wie man ein Monsteromelett zubereitet.\nVerkaufspreis:\nMonsteromelett\nBenötigt Stufe 40\nBenutzen: Stellt im Verlauf von 30 Sek. 1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 12 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Riesenei , Feine Gewürze (2)" }
entries[16111] = { ["name"] = "Rezept: Gewürzter Chilikrebs", ["text"] = "Benötigt Kochkunst (225)\nBenutzen: Lehrt Euch, wie man gewürzten Chilikrebs zubereitet.\nVerkaufspreis:\nGewürzter Chilikrebs\nBenötigt Stufe 40\nBenutzen: Stellt im Verlauf von 30 Sek. 1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 12 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Zartes Krebsfleisch , Scharfe Gewürze (2)" }
entries[16112] = { ["name"] = "Handbuch: Schwerer Seidenverband", ["text"] = "Benötigt Erste Hilfe (180)\nBenutzen: Lehrt Euch, wie man einen schweren Seidenverband herstellt.\nVerkaufspreis:\nSchwerer Seidenverband\nBenötigt Erste Hilfe (125)\nBenutzen: Heilt 8 Sek. lang insgesamt 640 Schaden.\nVerkaufspreis:\nBenötigt Seidenstoff (2)" }
