entries[16214] = { ["name"] = "Formel: Armschiene - Große Intelligenz", ["text"] = "Benötigt Verzauberkunst (255)\nBenutzen: Lehrt Euch, Armschienen dauerhaft so zu verzaubern, dass sie die Intelligenz um 7 erhöhen.\nVerzaubert Armschienen dauerhaft, sodass die Intelligenz um +7 erhöht wird.\nVerkaufspreis:" }
