entries[16216] = { ["name"] = "Formel: Umhang - Großer Widerstand", ["text"] = "Benötigt Verzauberkunst (265)\nBenutzen: Lehrt Euch, Umhänge dauerhaft so zu verzaubern, dass sie alle Widerstände um 5 erhöhen.\nEinen Umhang dauerhaft verzaubern, sodass alle Widerstände um 5 erhöht werden.\nVerkaufspreis:" }
