entries[16220] = { ["name"] = "Formel: Stiefel - Willenskraft", ["text"] = "Benötigt Verzauberkunst (275)\nBenutzen: Lehrt Euch, Stiefel dauerhaft so zu verzaubern, dass sie die Willenskraft um 5 erhöhen.\nStiefel dauerhaft verzaubern, sodass die Willenskraft um +5 erhöht wird.\nVerkaufspreis:" }
entries[16221] = { ["name"] = "Formel: Brust - Erhebliche Gesundheit", ["text"] = "Benötigt Verzauberkunst (275)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft so zu verzaubern, dass sie 100 zusätzliche Gesundheit gewähren.\nEin Teil der Brustrüstung dauerhaft verzaubern, sodass die Gesundheit um +100 erhöht wird.\nVerkaufspreis:" }
entries[16222] = { ["name"] = "Formel: Schild - Erhebliche Willenskraft", ["text"] = "Benötigt Verzauberkunst (280)\nBenutzen: Lehrt Euch, Schilde dauerhaft so zu verzaubern, dass sie die Willenskraft um 9 erhöhen.\nEinen Schild dauerhaft verzaubern, sodass die Willenskraft um +9 erhöht wird.\nVerkaufspreis:" }
entries[16223] = { ["name"] = "Formel: Waffe - Eisiger Hauch", ["text"] = "Benötigt Verzauberkunst (285)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie einen eisigen Hauch erhalten, der den Getroffenen manchmal langsamer werden lässt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass das Ziel oft mit Kälteeffekten belegt wird und sein Bewegungstempo sowie sein Angriffstempo verringert wird. Verringerter Effekt bei Spielern über Stufe 60.\nVerkaufspreis:" }
entries[16224] = { ["name"] = "Formel: Umhang - Überragende Verteidigung", ["text"] = "Benötigt Verzauberkunst (285)\nBenutzen: Lehrt Euch, Umhänge dauerhaft so zu verzaubern, dass sie die Rüstung um 70 erhöhen.\nEinen Umhang dauerhaft verzaubern, sodass die Rüstung zusätzlich um 70 erhöht wird.\nVerkaufspreis:" }
entries[16242] = { ["name"] = "Formel: Brust - Erhebliches Mana", ["text"] = "Benötigt Verzauberkunst (290)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft so zu verzaubern, dass sie 100 zusätzliche Mana gewähren.\nEinen Teil der Brustrüstung dauerhaft verzaubern, sodass das Mana um +100 erhöht wird.\nVerkaufspreis:" }
entries[16243] = { ["name"] = "Formel: Runenverzierte Arkanitrute", ["text"] = "Benötigt Verzauberkunst (290)\nBenutzen: Lehrt Euch die Herstellung einer runenverzierten Arkanitrute.\nVerkaufspreis:\nRunenverzierte Arkanitrute\nWird beim Aufheben gebunden\n\"Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"\nVerkaufspreis:\nBenötigt Arkanitrute , Goldene Perle , Illusionsstaub (10), Große ewige Essenz (4), Runenverzierte Echtsilberrute , Großer glänzender Splitter (2)" }
entries[16244] = { ["name"] = "Formel: Handschuhe - Große Stärke", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Handschuhe dauerhaft so zu verzaubern, dass sie die Stärke um 7 erhöhen.\nHandschuhe dauerhaft verzaubern, sodass die Stärke um +7 erhöht wird.\nVerkaufspreis:" }
