entries[16246] = { ["name"] = "Formel: Armschiene - Überragende Stärke", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Armschienen dauerhaft so zu verzaubern, dass sie die Stärke um 9 erhöhen.\nVerzaubert Armschienen dauerhaft, um +9 Stärke zu erhalten.\nVerkaufspreis:" }
entries[16247] = { ["name"] = "Formel: Zweihandwaffe - Überragender Einschlag", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft so zu verzaubern, dass sie 9 zusätzliche Schadenspunkte zufügen.\nEine Zweihand-Nahkampfwaffe dauerhaft verzaubern, sodass damit +9 Schaden zugefügt wird.\nVerkaufspreis:" }
entries[16248] = { ["name"] = "Formel: Waffe - Unheilig", ["text"] = "Benötigt Verzauberkunst (295)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie den Getroffenen gelegentlich verfluchen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass das Ziel oft mit einem Fluch belegt und der angerichtete Nahkampfschaden verringert wird.\nVerkaufspreis:" }
entries[16249] = { ["name"] = "Formel: Zweihandwaffe - Erhebliche Intelligenz", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft so zu verzaubern, dass sie die Intelligenz um 9 erhöhen.\nEine Zweihand-Nahkampfwaffe dauerhaft verzaubern, sodass sie die Intelligenz um 9 erhöht.\nVerkaufspreis:" }
entries[16250] = { ["name"] = "Formel: Waffe - Überragendes Schlagen", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie 5 zusätzliche Schaden zufügen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass damit 5 zusätzliche Punkte Schaden zugefügt werden.\nVerkaufspreis:" }
entries[16251] = { ["name"] = "Formel: Armschiene - Überragende Ausdauer", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Armschienen dauerhaft so zu verzaubern, dass sie die Ausdauer um 9 erhöhen.\nVerzaubert Armschienen dauerhaft, sodass die Ausdauer um +9 erhöht wird.\nVerkaufspreis:" }
entries[16252] = { ["name"] = "Formel: Waffe - Kreuzfahrer", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie ihren Benutzer gelegentlich mit großer Stärke segnen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie bei Nahkampfangriffen oft 75 bis 125 heilt und 15 Sek. lang die Stärke um 100 erhöht. Verringerter Effekt bei Spielern über Stufe 60.\nVerkaufspreis:" }
entries[16253] = { ["name"] = "Formel: Brust - Große Werte", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft so zu verzaubern, dass sie alle Werte um 4 erhöhen.\nEin Teil der Brustrüstung dauerhaft verzaubern, sodass alle Werte um +4 erhöht werden.\nVerkaufspreis:" }
entries[16254] = { ["name"] = "Formel: Waffe - Lebensdiebstahl", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft so zu verzaubern, dass sie gelegentlich etwas Gesundheit vom Feind stehlen und auf ihren Benutzer übertragen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass vom Feind oft Leben gestohlen und auf den Benutzer übertragen wird. Verringerter Effekt bei Spielern über Stufe 60.\nVerkaufspreis:" }
entries[16255] = { ["name"] = "Formel: Zweihandwaffe - Erhebliche Willenskraft", ["text"] = "Benötigt Verzauberkunst (300)\nBenutzen: Lehrt Euch, Zweihandwaffen dauerhaft so zu verzaubern, dass sie die Willenskraft um 9 erhöhen.\nEine Zweihand-Nahkampfwaffe dauerhaft verzaubern, sodass sie die Willenskraft um 9 erhöht.\nVerkaufspreis:" }
